function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),5200)}
async function api(path,body){const r=await fetch(path,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':state.csrf},body:JSON.stringify(body)});let data;try{data=await r.json()}catch{throw Error('无法读取本机服务，请确认光屿 AI 正在运行。')}if(!r.ok){const error=Error(data.error||`请求失败（${r.status}）`);error.httpStatus=r.status;throw error;}return data}
function providerUsable(p){const kinds=p.model_constraints?.kinds||[];return !kinds.length||kinds.includes(p.kind)}
function chosen(kind){return state.providers.find(p=>p.id===state.selected[kind]&&p.kind===kind&&providerUsable(p))||state.providers.find(p=>p.kind===kind&&providerUsable(p))}
function options(kind){const list=state.providers.filter(p=>p.kind===kind&&providerUsable(p));return list.length?list.map(p=>`<option value="${p.id}" ${chosen(kind)?.id===p.id?'selected':''}>${esc(p.name)} · ${esc(p.model)}</option>`).join(''):`<option value="">选择${kind==='chat'?'语言模型':kindNames[kind]+'模型'} · 请先接入</option>`}
function capabilities(p){return p?.capabilities||{}}
function capChips(p,limit=5){return Object.entries(capabilities(p)).filter(([,v])=>v).slice(0,limit).map(([k])=>`<span class="cap-chip enabled">${p.kind==='audio'&&k==='style'?'表演情绪':capabilityNames[k]}</span>`).join('')}
function heading(title,description,actions='',which=state.page){return `<div class="page-heading"><div><div class="heading-title">${icon(which)}<h1>${title}</h1></div><p>${description}</p></div><div class="heading-actions">${actions}</div></div>`}
function empty(which,title,description,action=''){return `<div class="empty-state">${icon(which)}<h3>${title}</h3><p>${description}</p>${action}</div>`}
function renderNavigation(){$('#main-nav').innerHTML=Object.entries(names).map(([key,name],i)=>`${key==='control'?'<div class="nav-group-label">项目与协作</div>':key==='image'?'<div class="nav-group-label">单项创作</div>':key==='usage'?'<div class="nav-group-label">资源与设置</div>':''}<button data-page="${key}" title="${name}" aria-label="${name}" class="${state.page===key?'active':''}">${icon(key)}<span>${name}</span></button>`).join('');$('#connection-count').textContent=`${state.providers.length} 个模型已接入`;$('#breadcrumb').textContent=names[state.page];$('#assistant-fab').innerHTML=icon('assistant')+'<span>网页 AI 助手</span>';$('#assistant-fab').hidden=!['image','video','audio','novel','visual'].includes(state.page)||$('#assistant-dialog').open}
function go(page){if(page==='projects')projectView.items=null;state.detail=null;closeAssistant();if(location.hash==='#'+page)render();else location.hash=page}
function render(){let hash=location.hash.slice(1);if(hash==='chat')hash='assistant';if(hash==='drafts')hash='control';const nextPage=names[hash]?hash:'control';if(state.page!==nextPage)window.scrollTo?.({top:0,left:0,behavior:'instant'});state.page=nextPage;document.body.dataset.workspace=state.page;renderNavigation();lastResultSignature='';if(['image','video'].includes(state.page))renderStudio(state.page);else if(state.page==='control')renderControl();else if(state.page==='projects')renderProjects();else if(state.page==='novel')renderNovelStudio();else if(state.page==='visual')renderVisualStudio();else if(state.page==='audio')renderAudio();else if(state.page==='assistant')renderAssistantPage();else if(state.page==='usage'){renderUsage();refreshUsage()}else if(state.page==='drafts')renderDrafts();else if(state.page==='history')renderHistory();else if(state.page==='materials')renderMaterials();else renderSettings()}

