function renderRecent(){const root=$('#recent-content');if(!root)return;const jobs=state.jobs.filter(j=>!j.work_deleted_at&&j.kind===state.page).slice(0,4);root.innerHTML=jobs.length?`<div class="recent-grid">${jobs.map(j=>{const a=j.result?.assets?.[0];return `<button class="recent-item ${j.id===currentJob(state.page)?.id?'selected':''}" data-select-job="${j.id}"><div class="recent-thumb">${mediaCover(a,j.prompt,j.kind)}</div><span>${esc(j.prompt)}</span></button>`}).join('')}</div>`:'<div class="empty-line">这里将收纳你的最近作品</div>'}
async function uploadFiles(files,kind,slot){
 const lock=kind+':'+slot;if(uploadLocks.has(lock))return toast('这一组素材正在上传，请等待完成后再添加');
 const d=state.drafts[kind],max=slot==='references'?Math.max(0,(chosen(kind)?.protocol==='weijin_video'?9:8)-d.assets.references.length):1;
 if(!max)return toast('已达到当前参考图数量上限');const list=files.slice(0,max);if(!list.length)return;
 uploadLocks.add(lock);state.uploading+=list.length;updateGenerate();
 try{
  for(const file of list){
   if(slot==='references'&&d.assets.references.length>=(chosen(kind)?.protocol==='weijin_video'?9:8))throw Error('已达到当前参考图数量上限');
   if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('仅支持 PNG、JPEG、WebP 图片');
   if(file.size>10*1024*1024)throw Error('单张图片不能超过 10 MiB');
   const raw=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(Error('无法读取这张图片'));reader.readAsDataURL(file)});
   const a=await api('/api/uploads',{name:file.name,data_base64:raw});state.assets[a.id]=a;
   if(slot==='references'){if(d.assets.references.length>=(chosen(kind)?.protocol==='weijin_video'?9:8))throw Error('已达到当前参考图数量上限');d.assets.references.push(a.id)}else d.assets[slot]=a.id;
  }
  if(slot==='references')d.mode='reference';else if(slot==='last_frame'||d.mode==='first_last')d.mode='first_last';else if(d.assets.first_frame)d.mode='first';
  toast('素材已保存到本机；提交生成时才会发送至模型');
 }catch(err){toast(err.message)}finally{uploadLocks.delete(lock);state.uploading-=list.length;if(state.page===kind)renderStudio(kind);else updateGenerate()}
}
function updateGenerate(){const b=$('#generate-button');if(b){b.disabled=!chosen(state.page)||state.busy||state.uploading>0;b.innerHTML=icon(state.page==='video'?'video':'spark')+(state.uploading?' 素材上传中…':state.page==='audio'?' 生成语音':state.page==='video'?' 生成视频':' 生成图像')}const send=$('[data-assistant-send]');if(send)send.disabled=state.busy||!chosen('chat')||state.jobs.some(j=>j.conversation_id===state.conversationId&&active(j))}
function payloadFor(kind){const d=state.drafts[kind],p=chosen(kind),caps=capabilities(p);const inputs={references:d.mode==='reference'?d.assets.references:[],first_frame:['first','first_last'].includes(d.mode)?d.assets.first_frame:null,last_frame:d.mode==='first_last'?d.assets.last_frame:null};if(d.mode==='reference'&&!inputs.references.length)throw Error('请先上传至少一张参考图');if(['first','first_last'].includes(d.mode)&&!inputs.first_frame)throw Error('请先上传首帧图片');if(d.mode==='first_last'&&!inputs.last_frame)throw Error('请先上传尾帧图片');const parameters=Object.fromEntries(Object.entries(d.parameters).filter(([k,v])=>v!==''&&v!=null&&caps[k==='n'?'batch':k]));return {provider_id:p?.id,prompt:d.prompt,size:d.size||'auto',seconds:d.seconds,input_assets:inputs,parameters,...(d.collection_id?{collection_id:d.collection_id}:{})}}
async function submitGeneration(e){e.preventDefault();if(state.busy||state.uploading)return;const kind=state.page;try{const payload=payloadFor(kind);state.busy=true;updateGenerate();const j=await api('/api/jobs',payload);state.jobs.unshift(j);state.currentJob[kind]=j.id;if(state.page===kind)updateResult(true);toast('任务已提交，生成状态会自动更新')}catch(err){toast(err.message)}finally{state.busy=false;updateGenerate()}}
function formatMessage(text){return String(text).split(/(```[\s\S]*?```)/g).map(part=>part.startsWith('```')?`<pre><code>${esc(part.replace(/^```[^\n]*\n?/,'').replace(/```$/,''))}</code></pre>`:esc(part).replace(/\*\*([^*\n]+)\*\*/g,'<strong>$1</strong>').replace(/`([^`\n]+)`/g,'<code>$1</code>')).join('')}
const assistantStarters=[['assistant','润色创作提示词','请帮我润色创作提示词，输出一段可直接使用的描述。'],['video','拆解视频分镜','请帮我将创意拆成镜头，分别说明画面、运动和节奏。'],['sliders','解释生成参数','请解释首帧、尾帧、种子和参考强度如何影响生成结果。'],['info','排查接口问题','我遇到了模型调用问题，请引导我检查协议、模型和参数。']];
function contextFromStudio(){const kind=['image','video'].includes(state.page)?state.page:state.assistantOrigin;const d=state.drafts[kind],p=chosen(kind);state.assistantOrigin=kind;return {page:names[kind],kind,prompt:d.prompt,model:p?.model||'',parameters:{...d.parameters,size:d.size,seconds:p?.mapped_controls?.seconds===false?null:d.seconds}}}
function assistantMarkup(drawer=false){return `<div class="assistant-area ${drawer?'':'panel'}">${drawer?`<div class="dialog-head"><h2 id="assistant-title">网页 AI 助手</h2><div><button class="icon-button" data-page="assistant" title="在完整页面打开" aria-label="在完整页面打开">${icon('expand')}</button><button class="icon-button" data-action="close-assistant" aria-label="关闭助手">${icon('close')}</button></div></div>`:''}<div class="assistant-toolbar"><div class="assistant-orb">${icon('assistant')}</div><div><h2>光屿创作助手</h2></div><label class="sr-only" for="assistant-model">助手模型</label><select id="assistant-model">${options('chat')}</select></div><div class="messages" id="assistant-messages"></div><form class="assistant-compose" id="assistant-form">${state.assistantContext?`<label class="context-toggle"><input type="checkbox" id="attach-context" ${state.attachContext?'checked':''}>附带${esc(state.assistantContext.page)}的当前草稿</label><div class="context-card" id="context-card" ${state.attachContext?'':'hidden'}>${icon(state.assistantContext.kind)} ${esc(state.assistantContext.prompt||'尚未填写描述')} · ${esc(state.assistantContext.model||'未选择模型')}</div>`:''}<label class="sr-only" for="assistant-input">向网页 AI 助手提问</label><textarea id="assistant-input" maxlength="32000" placeholder="描述你的想法，或向我询问网页用法…" required>${esc(state.assistantDraft)}</textarea><div class="compose-footer"><button type="submit" class="button primary" data-assistant-send ${!chosen('chat')||state.busy?'disabled':''}>发送 ${icon('send')}</button></div>${!chosen('chat')?'<p class="field-hint"><button type="button" class="text-button" data-add-kind="chat">接入语言模型 →</button></p>':''}</form></div>`}
function renderAssistantPage(){closeAssistant();if(chosen('chat'))state.selected.chat=chosen('chat').id;$('#page').innerHTML=`<div class="assistant-page"><aside class="panel conversation-panel"><button class="button secondary wide" data-action="new-conversation">${icon('plus')} 新建对话</button><div class="conversation-label">最近会话</div>${state.conversations.map(c=>`<button class="conversation ${c.id===state.conversationId?'active':''}" data-conversation="${c.id}" title="${esc(c.title)}">${esc(c.title)}</button>`).join('')}</aside>${assistantMarkup()}</div>`;bindAssistant();renderMessages(true)}
function openAssistant(polish=false){if(state.page==='assistant'){if(polish){state.assistantDraft=assistantStarters[0][2];renderAssistantPage()}return}state.assistantContext=contextFromStudio();state.attachContext=polish;state.assistantDraft=polish?'请优化我附带的创作描述，保留原始意图、加强构图和光影细节，只输出可直接使用的提示词。':state.assistantDraft;const dlg=$('#assistant-dialog');dlg.innerHTML=assistantMarkup(true);if(!dlg.open)dlg.showModal();renderNavigation();bindAssistant();renderMessages(true);$('#assistant-input').focus()}
function closeAssistant(){const dlg=$('#assistant-dialog');if(dlg.open)dlg.close();dlg.innerHTML='';if($('#assistant-fab'))$('#assistant-fab').hidden=!['image','video','audio','novel','visual'].includes(state.page)}
function bindAssistant(){$('#assistant-model').onchange=e=>{state.selected.chat=e.target.value;updateGenerate()};$('#assistant-input').oninput=e=>state.assistantDraft=e.target.value;$('#assistant-input').onkeydown=e=>{if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();$('#assistant-form').requestSubmit()}};$('#assistant-form').onsubmit=sendAssistant;const box=$('#attach-context');if(box)box.onchange=()=>{state.attachContext=box.checked;$('#context-card').hidden=!box.checked};assistantSignature='';updateGenerate()}
function renderMessages(force=false){const root=$('#assistant-messages');if(!root)return;const c=state.conversations.find(x=>x.id===state.conversationId);const job=state.jobs.find(j=>j.conversation_id===state.conversationId);const signature=JSON.stringify([c,job?.status,job?.error]);if(!force&&signature===assistantSignature)return;assistantSignature=signature;const nearBottom=root.scrollHeight-root.scrollTop-root.clientHeight<70;root.innerHTML=c?.messages.length?c.messages.map((m,i)=>`<article class="message ${m.role}"><div class="message-role">${m.role==='user'?'你':icon('assistant')+' 网页 AI 助手'}</div><div class="message-text">${formatMessage(m.content)}</div>${m.role==='assistant'?`<div class="message-actions"><button data-copy-message="${i}">${icon('copy')} 复制</button><button data-adopt="image" data-message="${i}">用于图像提示词</button><button data-adopt="video" data-message="${i}">用于视频描述</button></div>`:''}</article>`).join(''):`<div class="assistant-welcome"><div class="assistant-orb">${icon('assistant')}</div><h3>开始新的对话</h3><div class="assistant-starters">${assistantStarters.map(([ic,title],i)=>`<button data-starter="${i}">${icon(ic)}${title}</button>`).join('')}</div></div>`;if(job&&active(job))root.innerHTML+='<div class="notice"><span class="spinner"></span> 正在整理回答…</div>';else if(job&&job.status!=='succeeded')root.innerHTML+=`<div class="notice error">${esc(job.error)}</div>`;if(force||nearBottom)root.scrollTop=c?.messages.length?root.scrollHeight:0;updateGenerate()}
async function sendAssistant(e){
 e.preventDefault();if(state.busy||$('[data-assistant-send]').disabled)return;
 const p=chosen('chat'),convBefore=state.conversationId,versionBefore=conversationVersion,draftBefore=state.assistantDraft;
 state.busy=true;updateGenerate();
 try{
  const payload={provider_id:p.id,prompt:draftBefore,conversation_id:convBefore};
  if(state.attachContext&&state.assistantContext)payload.assistant_context=state.assistantContext;
  const j=await api('/api/jobs',payload);state.jobs.unshift(j);
  if(conversationVersion===versionBefore&&state.conversationId===convBefore){
   state.conversationId=j.conversation_id;
   if(state.assistantDraft===draftBefore){state.assistantDraft='';if($('#assistant-input'))$('#assistant-input').value=''}
  }
  state.conversations=(await api('/api/conversations')).conversations;
  if(state.page==='assistant')renderAssistantPage();else renderMessages(true);
 }catch(err){toast(err.message)}finally{state.busy=false;updateGenerate()}
}
function metric(title,value,note,ic){return `<div class="metric"><div class="metric-label">${title}${icon(ic)}</div><strong>${count(value)}</strong><small>${note}</small></div>`}
function chartHTML(report){const daily=report.daily.slice(-30);if(!daily.some(d=>d.usage_reported_requests>0))return '<div class="chart-empty">模型返回用量后，这里将显示每日 Token 趋势</div>';const max=Math.max(1,...daily.flatMap(x=>[x.input_tokens||0,x.output_tokens||0]));const width=720,height=170,gap=width/Math.max(1,daily.length);return `<svg class="usage-svg" viewBox="0 0 ${width} ${height}" role="img" aria-label="每日输入和输出 Token"><path d="M0 30H720M0 70H720M0 110H720M0 145H720" stroke="#eef1f7" fill="none"/>${daily.map((d,i)=>{const w=Math.min(18,gap*.28),x=i*gap+gap/2,hin=(d.input_tokens||0)/max*120,hout=(d.output_tokens||0)/max*120;return `<g><title>${esc(d.date)}：输入 ${count(d.input_tokens)} / 输出 ${count(d.output_tokens)}</title><rect x="${x-w-1}" y="${145-hin}" width="${w}" height="${hin}" rx="2" fill="#7f8cdc"/><rect x="${x+1}" y="${145-hout}" width="${w}" height="${hout}" rx="2" fill="#c1caf3"/>${daily.length<=10||i%Math.ceil(daily.length/8)===0?`<text x="${x}" y="164" text-anchor="middle" fill="#a3aec0" font-size="9">${esc(d.date.slice(5))}</text>`:''}</g>`}).join('')}</svg>`}
function renderUsage(){const r=state.usage;$('#page').innerHTML=heading('用量统计','查看模型调用与平台返回的消耗。',`<a class="button secondary" href="/api/usage.csv?period=${state.period}" download>${icon('download')} 导出 CSV</a>`)+`<div class="list-toolbar"><div class="segmented" aria-label="统计时间范围">${[['today','今天'],['7d','7 天'],['30d','30 天'],['all','全部']].map(([k,v])=>`<button data-period="${k}" class="${state.period===k?'active':''}">${v}</button>`).join('')}</div><button class="text-button" data-action="refresh-usage">${icon('refresh')} ${state.usageLoading?'刷新中':'刷新数据'}</button></div><div class="usage-intro">${icon('info')}<span>仅统计本工作台的 API 返回用量。未提供 Token 的请求显示 —；缓存和推理属于子集，不重复累计。</span></div><div id="usage-content">${state.usageError?`<div class="notice error">${esc(state.usageError)}</div>`:r?usageContents(r):'<div class="boot-state">正在读取模型与用量…</div>'}</div>`}
function usageContents(r){const s=r.summary;return `<div class="metric-grid">${metric('已记录 Token',s.total_tokens,`${s.token_complete_requests} 次总量可用 · ${s.token_incomplete_requests} 次总量不完整 / 未提供`,'usage')}${metric('输入 Token',s.input_tokens,`缓存输入 ${count(s.cached_input_tokens)} · 已含在输入中`,'arrow')}${metric('输出 Token',s.output_tokens,`推理输出 ${count(s.reasoning_tokens)} · 已含在输出中`,'assistant')}${metric('模型调用',s.requests,`成功 ${s.succeeded} · 失败 ${s.failed} · 进行中 ${s.active}`,'model')}</div><section class="panel usage-chart"><div class="panel-heading"><h2>用量趋势 <span class="micro">· 北京时间${r.daily.length>30?' · 仅显示最近 30 天':''}</span></h2><div class="chart-legend"><span><i class="legend-dot"></i>输入</span><span><i class="legend-dot output"></i>输出</span></div></div>${chartHTML(r)}<div class="canvas-info"><span>完成图像 ${s.image_count} 张 · 视频 ${s.video_count} 个 · 音频 ${s.audio_count||0} 段</span><span>平均耗时 ${elapsed(s.avg_latency_ms)}</span></div></section><section class="panel table-panel"><div class="panel-heading"><h2>接入模型 <span class="micro">${s.connected_models} 个当前连接${s.historical_models?' · '+s.historical_models+' 个历史版本':''}</span></h2><button class="text-button" data-page="settings">管理连接 ${icon('arrow')}</button></div><div class="table-wrap"><table><thead><tr><th>模型 / 连接</th><th>用途与协议</th><th>调用次数</th><th>输入 Token</th><th>输出 Token</th><th>总 Token</th><th>状态</th></tr></thead><tbody>${r.models.length?r.models.map(m=>`<tr><td><div class="table-model"><div class="table-model-icon">${icon(m.kind==='chat'?'assistant':m.kind)}</div><div><strong>${esc(m.model)}</strong><small>${esc(m.provider_name)}</small></div></div></td><td>${kindNames[m.kind]||esc(m.kind)}<small>${esc(protocolNames[m.protocol]||m.protocol)}</small></td><td>${m.requests}<small>成功 ${m.succeeded} · 失败 ${m.failed}</small></td><td>${count(m.input_tokens)}</td><td>${count(m.output_tokens)}</td><td>${count(m.total_tokens)}<small>${m.token_incomplete_requests?m.token_incomplete_requests+' 次总量不完整 / 未提供':''}</small></td><td><span class="${m.connected?'connected-tag':'historical-tag'}">${m.connected?'已接入':'历史连接'}</span></td></tr>`).join(''):'<tr><td colspan="7" class="table-empty">尚未接入模型。添加 API 连接后会自动显示在这里。</td></tr>'}</tbody></table></div></section><section class="panel table-panel"><div class="panel-heading"><h2>请求明细</h2><span class="micro">最近 ${r.requests.length} 条 · CSV 可导出全部</span></div><div class="table-wrap"><table><thead><tr><th>时间</th><th>模型</th><th>用途</th><th>状态</th><th>Token</th><th>耗时</th></tr></thead><tbody>${r.requests.length?r.requests.map(j=>`<tr><td>${timeLabel(j.created_at)}</td><td><strong>${esc(j.model)}</strong><small>${esc(j.provider_name)}</small></td><td>${kindNames[j.kind]}</td><td>${badge(j)}</td><td>${count(j.total_tokens)}<small>${j.total_tokens==null?'平台未提供':''}</small></td><td>${elapsed(j.elapsed_ms)}</td></tr>`).join(''):'<tr><td class="table-empty" colspan="6">这个时间范围内还没有调用记录</td></tr>'}</tbody></table></div></section><p class="usage-footnote">统计来自本机保存的接口响应，不能代表平台账户余额或完整账单。图像和视频可能按张数、秒数计费；未报告的 Token 不按 0 处理，汇总仅累加已知部分；总量不完整的请求不代表 0 消耗。历史记录没有返回用量的部分无法追溯补齐。</p>`}
async function refreshUsage(){const revision=++usageVersion;state.usageLoading=true;state.usageError='';try{const r=await api('/api/usage?period='+state.period);if(revision!==usageVersion)return;state.usage=r}catch(err){if(revision===usageVersion)state.usageError=err.message}finally{if(revision===usageVersion){state.usageLoading=false;if(state.page==='usage')renderUsage()}}}
function fieldHTML(name,label,value='',options={}){const {type='text',placeholder='',required=false}=options;return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" placeholder="${esc(placeholder)}" ${required?'required':''} ${type==='password'?'autocomplete="new-password"':''}></label>`}
function renderHistory(){if(!state.detail)return renderCollections();const works=libraryWorks();if(!['all','saved','unsaved','image','video','audio'].includes(state.filter))state.filter='all';const job=works.find(j=>j.id===state.detail);if(job){$('#page').innerHTML=heading('创作详情',`${esc(job.provider_name)} · ${timeLabel(job.created_at)}`,`<button class="button secondary" data-action="back-history">返回记录</button>`)+`<div class="detail-layout"><section class="canvas-panel">${job.kind==='chat'?`<div class="message-text">${formatMessage(job.result?.text||job.error||statusNames[job.status])}</div>`:resultHTML(job)}<div class="detail-prompt">${esc(job.prompt)}</div></section><aside class="panel detail-inspector"><h3>任务信息</h3><dl><dt>模型</dt><dd>${esc(job.response_model||job.model)}</dd><dt>状态</dt><dd>${badge(job)}</dd><dt>耗时 / Token</dt><dd>${elapsed(job.elapsed_ms)} · ${count((job.usage||job.result?.usage)?.total_tokens)}</dd><dt>平台任务 ID</dt><dd>${esc(job.upstream_id||'—')}</dd><dt>高级参数</dt><dd>${esc(JSON.stringify(job.parameters||{}))}</dd><dt>输入素材</dt><dd>${job.input_assets?.references?.length||0} 张参考图${job.input_assets?.first_frame?' · 首帧':''}${job.input_assets?.last_frame?' · 尾帧':''}</dd></dl><button class="button secondary wide reuse-button" data-reuse="${job.id}">${icon('copy')} 复用创作设置</button>${deleteWorkButton(job,true)}</aside></div>`;return}state.detail=null;const list=works.filter(j=>state.filter==='all'||j.kind===state.filter||(state.filter==='saved'&&j.archive_status==='saved')||(state.filter==='unsaved'&&j.result?.assets?.some(a=>!a.local)));$('#page').innerHTML=heading('作品库','收纳生成成功的图片、视频和音频，自动保存到本机，随时查看与下载。')+librarySummary()+`<div class="list-toolbar"><div class="segmented">${[['all','全部'],['saved','已保存'],['unsaved','待保存'],['image','图像'],['video','视频'],['audio','音频']].map(([k,t])=>`<button data-history-filter="${k}" class="${state.filter===k?'active':''}">${t}</button>`).join('')}</div><span class="micro">显示 ${list.length} / ${works.length} 项作品</span></div><div class="history-grid">${list.map(j=>{const a=j.result?.assets?.[0];return `<article class="panel history-card"><button class="history-preview wide" data-detail="${j.id}" aria-label="查看创作 ${esc(j.prompt.slice(0,30))}">${mediaCover(a,j.prompt,j.kind)}${badge(j)}</button><div class="history-card-body">${archiveLabel(j)}<h3 title="${esc(j.prompt)}">${esc(j.prompt)}</h3><div class="history-card-meta"><span>${esc(j.model)}</span><span>${timeLabel(j.created_at)}</span></div><div class="history-card-actions"><button class="button secondary" data-detail="${j.id}">查看详情 ${icon('arrow')}</button>${deleteWorkButton(j)}</div></div></article>`}).join('')}</div>${!list.length?`<section class="panel">${empty('history','暂无符合条件的作品','生成成功的图片、视频和音频会显示在这里。')}</section>`:''}`}
async function reuseJob(id){const j=state.jobs.find(x=>x.id===id);if(!j)return;if(typeof creative!=='undefined')delete creative.draftId[j.kind];if(j.kind==='chat'){conversationVersion++;state.assistantDraft=j.prompt;go('assistant');return}const d=state.drafts[j.kind];d.prompt=j.prompt;d.size=j.size;d.seconds=j.seconds;d.parameters={...(j.parameters||{})};d.collection_id=j.collection_id||(j.visual_project_id?'visual:'+j.visual_project_id:j.storyboard_id?'storyboard:'+j.storyboard_id:'');d.assets={references:[],first_frame:null,last_frame:null,...j.input_assets};const ids=[...d.assets.references,d.assets.first_frame,d.assets.last_frame].filter(Boolean);try{for(const identity of ids){if(!state.assets[identity])state.assets[identity]=await api('/api/uploads/'+identity)}}catch{toast('部分素材不可用，已保留提示词和参数');d.assets={references:[],first_frame:null,last_frame:null}}d.mode=d.assets.last_frame&&d.assets.first_frame?'first_last':d.assets.first_frame?'first':d.assets.references.length?'reference':'text';state.selected[j.kind]=j.provider_id;go(j.kind)}
function previewAsset(a,title='作品预览'){if(!a)return toast('生成完成后可放大预览');const dlg=$('#asset-dialog');dlg.innerHTML=`<div class="dialog-head"><h2>${esc(title)}</h2><button class="icon-button" data-action="close-asset" aria-label="关闭大图">${icon('close')}</button></div>${a.type==='audio'?`<div class="audio-result">${icon('audio')}<strong>AI 生成语音</strong><audio src="${esc(a.url)}" controls preload="metadata"></audio></div>`:a.type==='video'?`<video src="${esc(a.url)}" ${a.poster_url?`poster="${esc(a.poster_url)}"`:""} controls playsinline></video>`:`<img src="${esc(a.url)}" alt="${esc(title)}">`}`;dlg.showModal()}
function confirmAction(title,text,confirmLabel='确认'){return new Promise(resolve=>{const dlg=$('#confirm-dialog');dlg.innerHTML=`<div class="dialog-head"><h2 id="confirm-title">${esc(title)}</h2></div><div class="dialog-content">${esc(text)}</div><div class="dialog-footer"><button class="button secondary" id="confirm-cancel">取消</button><button class="button danger" id="confirm-ok">${esc(confirmLabel)}</button></div>`;let result=false;$('#confirm-ok').onclick=()=>{result=true;dlg.close()};$('#confirm-cancel').onclick=()=>dlg.close();dlg.addEventListener('close',()=>resolve(result),{once:true});dlg.showModal()})}
function deleteWorkButton(job,wide=false){return `<button class="button secondary work-delete ${wide?'wide':''}" data-delete-work="${job.id}" ${job.archive_status==='pending'?'disabled title="作品正在保存，请稍后删除"':''}>${icon('trash')} 删除作品</button>`}
const deletingWorks=new Set();
async function deleteWork(identity){
  const job=libraryWorks().find(j=>j.id===identity);if(!job||deletingWorks.has(identity))return;
  deletingWorks.add(identity);
  try{
    if(!await confirmAction('删除这次生成的作品？',`将从作品库移除这次生成的全部 ${job.result.assets.length} 件作品，并永久删除本机对应文件，无法撤销。已下载到其他位置的副本、上传的参考素材和历史用量统计会保留。`,'删除作品'))return;
    const deleted=await api('/api/jobs/delete',{id:identity});
    state.jobs=state.jobs.map(j=>j.id===identity?deleted:j);
    for(const kind of ['image','video','audio'])if(state.currentJob[kind]===identity)delete state.currentJob[kind];
    delete state.assetIndex[identity];if(state.detail===identity)state.detail=null;
    render();toast(deleted.work_cleanup_pending?.length?'已从作品库删除；部分文件被占用，将在下次启动时继续清理。':'作品及本机文件已删除，用量统计已保留');
  }catch(error){toast(error.message)}finally{deletingWorks.delete(identity)}
}
const prompts={image:['一瓶透明玻璃香水置于深色石材上，侧逆光勾勒瓶身，清晰水珠，低饱和度，高端商业产品摄影。','临海的极简美术馆，挑高空间，暖白墙面，午后阳光穿过格栅形成柔和阴影，建筑摄影，留白构图。','雨后的城市街道，路灯倒映在积水里，撑伞的背影走向远处，电影质感，蓝金色调，浅景深。'],video:['夜色街道里，一个行人缓慢经过橱窗，镜头平稳跟随，霓虹灯映入积水，细腻的电影光影，克制的节奏。','一只银色耳机置于深色背景，镜头缓慢环绕，柔和边缘光勾勒金属细节，干净的产品广告镜头。','清晨松林笼罩薄雾，阳光穿过树冠，镜头缓慢向前推进，叶片随风轻动，自然纪录片质感。']};
document.addEventListener('click',async e=>{const el=e.target.closest('button,[data-preview-upload],[data-expand-job]');if(!el)return;
 if(el.dataset.deleteWork)return deleteWork(el.dataset.deleteWork);
 if(el.dataset.action==='reset-image-parameters'){resetImageParameters();renderStudio('image');toast('已恢复默认参数，描述和参考图已保留');return}
 if(el.dataset.action==='apply-video-direction'){applyVideoDirections();return}
 if(el.dataset.action==='swap-video-frames'){const d=state.drafts.video;[d.assets.first_frame,d.assets.last_frame]=[d.assets.last_frame,d.assets.first_frame];renderStudio('video');return}
 if(el.dataset.copyMaterial){const item=materialCatalog.find(x=>x.id===el.dataset.copyMaterial);if(!item)return;try{await navigator.clipboard.writeText(item.url);toast('素材链接已复制')}catch{toast('无法访问剪贴板，可右键“查看素材与提示词”复制链接')}return}
 if(el.dataset.page)return go(el.dataset.page);
 if(el.dataset.mode){state.drafts[state.page].mode=el.dataset.mode;return renderStudio(state.page)}
 if(el.dataset.size){state.drafts[state.page].size=el.dataset.size;$('#size-input').value=el.dataset.size;document.querySelectorAll('[data-size]').forEach(b=>b.classList.toggle('active',b===el));return}
 if(el.dataset.param)return;
 if(el.dataset.preset!==undefined){state.drafts[state.page].prompt=prompts[state.page][Number(el.dataset.preset)];$('#prompt').value=state.drafts[state.page].prompt;$('#prompt-count').textContent=`${state.drafts[state.page].prompt.length} / 32000`;$('#prompt').focus();return}
 if(el.dataset.removeAsset){const d=state.drafts[state.page],slot=el.dataset.removeAsset;if(slot==='references')d.assets.references.splice(Number(el.dataset.index),1);else d.assets[slot]=null;return renderStudio(state.page)}
 if(el.dataset.previewUpload)return previewAsset(state.assets[el.dataset.previewUpload],'上传素材');
 if(el.dataset.expandJob)return previewAsset(currentAsset(state.jobs.find(j=>j.id===el.dataset.expandJob)));
 if(el.dataset.selectJob){state.currentJob[state.page]=el.dataset.selectJob;return updateResult(true)}
 if(el.dataset.assetIndex!==undefined){state.assetIndex[el.dataset.job]=Number(el.dataset.assetIndex);return state.page==='history'?renderHistory():updateResult(true)}
 if(el.dataset.period){state.period=el.dataset.period;state.usage=null;renderUsage();return refreshUsage()}
 if(el.dataset.historyFilter){state.filter=el.dataset.historyFilter;return renderHistory()}
 if(el.dataset.detail){state.detail=el.dataset.detail;return renderHistory()}
 if(el.dataset.reuse)return reuseJob(el.dataset.reuse);
 if(el.dataset.discoverProvider)return editProvider(el.dataset.discoverProvider,null,{autoDiscover:true});
 if(el.dataset.edit)return editProvider(el.dataset.edit);
 if(el.dataset.addKind)return editProvider(null,el.dataset.addKind);
 if(el.dataset.conversation){conversationVersion++;state.conversationId=el.dataset.conversation;return renderAssistantPage()}
 if(el.dataset.starter!==undefined){state.assistantDraft=assistantStarters[Number(el.dataset.starter)][2];$('#assistant-input').value=state.assistantDraft;$('#assistant-input').focus();return}
 if(el.dataset.copyMessage!==undefined){const c=state.conversations.find(x=>x.id===state.conversationId);try{await navigator.clipboard.writeText(c.messages[Number(el.dataset.copyMessage)].content);toast('已复制回答')}catch{toast('无法访问剪贴板，请选中文字复制')}return}
 if(el.dataset.adopt){const c=state.conversations.find(x=>x.id===state.conversationId);const text=c.messages[Number(el.dataset.message)].content,kind=el.dataset.adopt;if(state.drafts[kind].prompt&&!await confirmAction('替换当前创作描述？','已有草稿将被这段助手回答替换，尚未提交生成。'))return;state.drafts[kind].prompt=text;go(kind);toast('已采用到创作描述，确认参数后可自行生成');return}
 if(el.dataset.archive){el.disabled=true;try{const j=await api('/api/jobs/archive',{id:el.dataset.archive});state.jobs=state.jobs.map(x=>x.id===j.id?j:x);state.page==='history'?renderHistory():updateResult(true);toast('正在保存原作品，不会重新提交生成')}catch(err){toast(err.message);el.disabled=false}return}
 if(el.dataset.resume){el.disabled=true;try{const j=await api('/api/jobs/resume',{id:el.dataset.resume});state.jobs=state.jobs.map(x=>x.id===j.id?j:x);state.page==='history'?renderHistory():updateResult(true);toast('继续查询原任务，不会重新提交生成')}catch(err){toast(err.message);el.disabled=false}return}
 if(el.dataset.check){el.disabled=true;try{const r=await api('/api/providers/check',{id:el.dataset.check});const p=state.providers.find(x=>x.id===el.dataset.check);toast(`模型列表可访问，返回 ${r.models.length} 项。${r.models.includes(p.model)||r.models.includes('models/'+p.model)?'已找到当前模型。':'未在列表中找到当前模型。'}生成能力仍需实际验证。`)}catch(err){toast(err.message)}finally{el.disabled=false}return}
 if(el.dataset.delete){const p=state.providers.find(x=>x.id===el.dataset.delete);if(!await confirmAction('删除模型连接？',`删除“${p.name}”的连接设置。已有创作记录和用量历史会保留。`))return;try{await api('/api/providers/delete',{id:p.id});state.providers=state.providers.filter(x=>x.id!==p.id);state.usage=null;render();toast('连接已删除，历史记录已保留')}catch(err){toast(err.message)}return}
 const action=el.dataset.action;
 if(action==='add-provider')return editProvider();
 if(action==='close-provider')return closeProvider();
 if(action==='open-assistant')return openAssistant();
 if(action==='polish')return openAssistant(true);
 if(action==='close-assistant')return closeAssistant();
 if(action==='expand-result')return previewAsset(currentAsset(currentJob(state.page)));
 if(action==='close-asset')return $('#asset-dialog').close();
 if(action==='refresh-usage')return refreshUsage();
 if(action==='back-history'){state.detail=null;return renderHistory()}
 if(action==='new-conversation'){conversationVersion++;state.conversationId=null;state.assistantDraft='';return renderAssistantPage()}
});
document.addEventListener('error',event=>{const el=event.target;if(!el.dataset?.videoCover)return;const video=document.createElement('video');video.src=el.dataset.videoCover+'#t=0.1';video.muted=true;video.playsInline=true;video.preload='metadata';el.replaceWith(video)},true);
$('#assistant-dialog').addEventListener('close',()=>{$('#assistant-dialog').innerHTML='';$('#assistant-fab').hidden=!['image','video','audio','novel','visual'].includes(state.page)});
$('#provider-dialog').addEventListener('close',()=>{const input=$('#provider-form [name=api_key]');if(input)input.value=''});
$('#asset-dialog').addEventListener('close',()=>$('#asset-dialog').innerHTML='');
window.addEventListener('hashchange',()=>{state.detail=null;render()});
async function pollJobs(){if(polling||!state.jobs.some(j=>active(j)||j.archive_status==='pending'))return;polling=true;try{const jobs=(await api('/api/jobs')).jobs;const changed=JSON.stringify(jobs)!==JSON.stringify(state.jobs);const chatChanged=JSON.stringify(jobs.filter(j=>j.kind==='chat'))!==JSON.stringify(state.jobs.filter(j=>j.kind==='chat'));if(chatChanged)state.conversations=(await api('/api/conversations')).conversations;state.jobs=jobs;if(changed){state.usage=null;if(['image','video','audio'].includes(state.page))updateResult();else if(state.page==='history')renderHistory();else if(state.page==='usage')refreshUsage();renderMessages();updateGenerate()}}catch{toast('暂时无法连接本机服务，任务记录仍保存在电脑上。')}finally{polling=false}}
async function init(){try{Object.assign(state,await api('/api/bootstrap'));render();setInterval(pollJobs,2500)}catch(err){$('#page').innerHTML=empty('info','无法读取本机工作区',esc(err.message),'<button class="button primary" id="retry-bootstrap">重新连接</button>');$('#retry-bootstrap').onclick=()=>location.reload()}}
// Render only after all deferred workbench extensions have registered.
if(document.readyState==='complete')init();else document.addEventListener('DOMContentLoaded',init,{once:true});
